shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const path = 'src/orchestration/chatOrchestrator.test.ts';
let content = fs.readFileSync(path, 'utf8');

const importToReplace = `import type {OrchestratorHooks} from './chatOrchestrator.js';`;
const importReplacement = `import type {OrchestratorHooks, AggregateUsage} from './chatOrchestrator.js';`;
content = content.replace(importToReplace, importReplacement);

const testCode = `
  it('sums usage from every provider call in a turn with multiple rounds', async () => {
    let seen: AggregateUsage | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [{type: 'text', text: 'done'}, STOP_DONE, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 3, totalTokens: 23}}],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual({inputTokens: 30, outputTokens: 5, totalTokens: 35});
  });
`;

const targetIndex = content.indexOf(`  it('keeps the usage an earlier round reported when a later round reports none'`);
if (targetIndex === -1) {
  console.log("Could not find the target index");
  process.exit(1);
}

content = content.slice(0, targetIndex) + testCode.trim() + '\n\n  ' + content.slice(targetIndex);
fs.writeFileSync(path, content);
console.log("Patched test");
EOF
node patch.js
